#!/usr/bin/env python3
"""Persistent dependency-free HTTP key-value service."""

from __future__ import annotations

import argparse
import json
import math
import os
import signal
import sys
import tempfile
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from typing import Any
from urllib.parse import unquote_to_bytes, urlsplit


MAX_BODY = 1024 * 1024
KV_PREFIX = "/v1/kv/"


class BadRequest(ValueError):
    pass


class Store:
    def __init__(self, path: Path) -> None:
        self.path = path
        self.lock = threading.RLock()
        self.entries: dict[str, dict[str, Any]] = {}
        self._load()

    @staticmethod
    def _live(entry: dict[str, Any], now: float) -> bool:
        expires_at = entry.get("expires_at")
        return expires_at is None or expires_at > now

    def _load(self) -> None:
        try:
            with self.path.open("r", encoding="utf-8") as source:
                loaded = json.load(source)
            if not isinstance(loaded, dict):
                raise ValueError("data file root must be an object")
            entries = loaded.get("entries", loaded)
            if not isinstance(entries, dict):
                raise ValueError("entries must be an object")
            now = time.time()
            for key, entry in entries.items():
                if not isinstance(key, str) or not isinstance(entry, dict) or "value" not in entry:
                    raise ValueError("invalid entry")
                expires_at = entry.get("expires_at")
                if expires_at is not None and (isinstance(expires_at, bool) or not isinstance(expires_at, (int, float)) or not math.isfinite(expires_at)):
                    raise ValueError("invalid expiry")
                if self._live(entry, now):
                    self.entries[key] = {"value": entry["value"], "expires_at": expires_at}
            if self.entries != entries:
                self._persist()
        except FileNotFoundError:
            return
        except (OSError, ValueError, json.JSONDecodeError) as error:
            raise RuntimeError(f"cannot load data file {self.path}: {error}") from error

    def _purge(self, now: float) -> bool:
        expired = [key for key, entry in self.entries.items() if not self._live(entry, now)]
        for key in expired:
            del self.entries[key]
        return bool(expired)

    def _persist(self) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        fd, temporary = tempfile.mkstemp(prefix=f".{self.path.name}.", dir=self.path.parent)
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as output:
                json.dump({"entries": self.entries}, output, ensure_ascii=False, separators=(",", ":"), allow_nan=False)
                output.write("\n")
                output.flush()
                os.fsync(output.fileno())
            os.replace(temporary, self.path)
        except BaseException:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass
            raise

    def put(self, key: str, value: Any, ttl: float | None) -> bool:
        with self.lock:
            now = time.time()
            self._purge(now)
            created = key not in self.entries
            self.entries[key] = {"value": value, "expires_at": None if ttl is None else now + ttl}
            self._persist()
            return created

    def get(self, key: str) -> tuple[bool, Any]:
        with self.lock:
            if self._purge(time.time()):
                self._persist()
            entry = self.entries.get(key)
            return (False, None) if entry is None else (True, entry["value"])

    def delete(self, key: str) -> bool:
        with self.lock:
            changed = self._purge(time.time())
            present = key in self.entries
            if present:
                del self.entries[key]
                changed = True
            if changed:
                self._persist()
            return present

    def keys(self) -> list[str]:
        with self.lock:
            if self._purge(time.time()):
                self._persist()
            return sorted(self.entries)


def decode_key(path: str) -> str:
    encoded = path[len(KV_PREFIX):]
    if not encoded or "/" in encoded:
        raise BadRequest("key must be non-empty and must not contain '/'")
    try:
        key = unquote_to_bytes(encoded).decode("utf-8")
    except UnicodeDecodeError as error:
        raise BadRequest("key must be valid UTF-8") from error
    if not key or "/" in key:
        raise BadRequest("key must be non-empty and must not contain '/'")
    return key


class Server(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True

    def __init__(self, address: tuple[str, int], store: Store) -> None:
        super().__init__(address, Handler)
        self.store = store


class Handler(BaseHTTPRequestHandler):
    server: Server

    def log_message(self, format: str, *args: Any) -> None:
        print(f"{self.address_string()} - {format % args}", file=sys.stderr)

    def _json(self, status: int, payload: Any) -> None:
        body = json.dumps(payload, ensure_ascii=False, separators=(",", ":"), allow_nan=False).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def _error(self, status: int, message: str) -> None:
        self._json(status, {"error": message})

    def _path(self) -> str:
        return urlsplit(self.path).path

    def _read_body(self) -> Any:
        raw_length = self.headers.get("Content-Length")
        if raw_length is None:
            raise BadRequest("Content-Length is required")
        try:
            length = int(raw_length)
        except ValueError as error:
            raise BadRequest("invalid Content-Length") from error
        if length < 0:
            raise BadRequest("invalid Content-Length")
        if length > MAX_BODY:
            self.close_connection = True
            raise OverflowError
        body = self.rfile.read(length)
        try:
            return json.loads(body)
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise BadRequest("malformed JSON") from error

    def do_GET(self) -> None:
        path = self._path()
        if path == "/health":
            self._json(200, {"status": "ok"})
            return
        if path == "/v1/keys":
            self._json(200, {"keys": self.server.store.keys()})
            return
        if path.startswith(KV_PREFIX):
            try:
                key = decode_key(path)
            except BadRequest as error:
                self._error(400, str(error))
                return
            found, value = self.server.store.get(key)
            if found:
                self._json(200, {"key": key, "value": value})
            else:
                self._error(404, "key not found")
            return
        self._error(404, "route not found")

    def do_PUT(self) -> None:
        path = self._path()
        if not path.startswith(KV_PREFIX):
            self._error(404, "route not found")
            return
        try:
            key = decode_key(path)
            payload = self._read_body()
            if not isinstance(payload, dict) or "value" not in payload or set(payload) - {"value", "ttl_seconds"}:
                raise BadRequest("body must be an object containing value and optional ttl_seconds")
            ttl = payload.get("ttl_seconds")
            if ttl is not None and (isinstance(ttl, bool) or not isinstance(ttl, (int, float)) or not math.isfinite(ttl) or ttl <= 0):
                raise BadRequest("ttl_seconds must be finite and greater than zero")
            created = self.server.store.put(key, payload["value"], ttl)
        except OverflowError:
            self._error(413, "request body exceeds 1 MiB")
            return
        except BadRequest as error:
            self._error(400, str(error))
            return
        except (OSError, ValueError) as error:
            self.log_error("persistence failure: %s", error)
            self._error(500, "persistence failure")
            return
        self._json(201 if created else 200, {"key": key, "value": payload["value"]})

    def do_DELETE(self) -> None:
        path = self._path()
        if not path.startswith(KV_PREFIX):
            self._error(404, "route not found")
            return
        try:
            key = decode_key(path)
        except BadRequest as error:
            self._error(400, str(error))
            return
        if not self.server.store.delete(key):
            self._error(404, "key not found")
            return
        self.send_response(204)
        self.end_headers()

    def _unsupported(self) -> None:
        self._error(405, "method not allowed")

    do_POST = _unsupported
    do_PATCH = _unsupported
    do_OPTIONS = _unsupported
    do_HEAD = _unsupported


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", type=int, required=True)
    parser.add_argument("--data", type=Path, required=True)
    args = parser.parse_args()
    if not 0 <= args.port <= 65535:
        parser.error("--port must be between 0 and 65535")
    return args


def main() -> int:
    args = parse_args()
    try:
        server = Server((args.host, args.port), Store(args.data))
    except (OSError, RuntimeError) as error:
        print(f"error: {error}", file=sys.stderr)
        return 1

    stopping = threading.Event()

    def stop(_signum: int, _frame: Any) -> None:
        if not stopping.is_set():
            stopping.set()
            threading.Thread(target=server.shutdown, daemon=True).start()

    signal.signal(signal.SIGTERM, stop)
    signal.signal(signal.SIGINT, stop)
    print(f"LISTENING {server.server_address[1]}", flush=True)
    try:
        server.serve_forever()
    finally:
        server.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

